<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {catalogListingOptions,confirmCatalogListing} from '@/api/modules/partnerOperations'
import {newRequestId,partnerPage} from '@/api/modules/partner'
import type {CatalogListingOptions} from '@/types/partnerLifecycle'
import type {SelectionRow} from '@/types/partnerSelections'
import type {PartnerRow} from '@/types/partner'
import {partnerError} from '@/utils/partnerError'
import PartnerPhoto from '../PartnerPhoto.vue'
import OperationSpecPicker from './OperationSpecPicker.vue'
const props=defineProps<{selectionId:number;row:SelectionRow}>(),emit=defineEmits<{close:[];saved:[row:PartnerRow]}>()
const options=ref<CatalogListingOptions>(),loading=ref(false),busy=ref(false),error=ref(''),selected=ref<string[]>([]),photos=ref<number[]>([]),name=ref(''),introduction=ref(''),mode=ref<'create'|'existing'>('create'),productId=ref<number>(),productVersion=ref<number>(),products=ref<PartnerRow[]>([]),specs=ref<Record<string,number|undefined>>({}),newSpecs=ref<Record<string,boolean>>({}),configurationConfirmed=ref<Record<string,boolean>>({}),baseline=ref(''),requestId=ref(newRequestId())
let generation=0
const key=(p:{phoneModelId:number;colorId:number})=>`${p.phoneModelId}:${p.colorId}`
const selectedPairs=computed(()=>options.value?.pairs.filter(p=>selected.value.includes(key(p)))||[])
const snapshot=()=>JSON.stringify([selected.value,photos.value,name.value,introduction.value,mode.value,productId.value,specs.value,newSpecs.value,configurationConfirmed.value])
const valid=computed(()=>!!options.value&&!!name.value.trim()&&!!introduction.value.trim()&&!!photos.value.length&&!!selectedPairs.value.length&&selectedPairs.value.every(p=>p.eligible)&&(mode.value==='create'||!!productId.value&&!!productVersion.value&&selectedPairs.value.every(p=>newSpecs.value[key(p)]||!!specs.value[key(p)]&&configurationConfirmed.value[key(p)])))
async function load(){const serial=++generation;loading.value=true;error.value='';try{const result=await catalogListingOptions(props.selectionId,props.row.rowId);if(serial!==generation)return;options.value=result;name.value=result.name;photos.value=result.photos.map(p=>p.id);baseline.value=snapshot()}catch(e){if(serial===generation)error.value=partnerError(e)}finally{if(serial===generation)loading.value=false}}
watch(()=>[props.selectionId,props.row.rowId],()=>{options.value=undefined;selected.value=[];specs.value={};void load()},{immediate:true})
watch([mode,productId],()=>{specs.value={};newSpecs.value={};configurationConfirmed.value={};productVersion.value=products.value.find(p=>p.id===productId.value)?.version})
onBeforeUnmount(()=>{generation++})
async function searchProducts(keyword:string){try{products.value=(await partnerPage('partner-products',{keyword,page:1,size:20})).content}catch(e){error.value=partnerError(e)}}
async function close(){if(busy.value)return;if(snapshot()!==baseline.value)try{await ElMessageBox.confirm('放弃本次尚未确认的上架资料？','保留填写',{confirmButtonText:'放弃并关闭',cancelButtonText:'继续填写',closeOnClickModal:false})}catch{return}emit('close')}
async function submit(){if(!valid.value||!options.value||busy.value)return;const data=options.value;busy.value=true;error.value='';try{const result=await confirmCatalogListing({selectionId:props.selectionId,selectionRowId:props.row.rowId,selectionVersion:data.selectionVersion,selectionRowVersion:data.selectionRowVersion,selectedPairs:selectedPairs.value.map(({phoneModelId,colorId})=>({phoneModelId,colorId})),productLinkMode:mode.value,...(mode.value==='existing'?{existingProductId:productId.value,existingProductVersion:productVersion.value,specLinks:selectedPairs.value.map(p=>({phoneModelId:p.phoneModelId,colorId:p.colorId,...(newSpecs.value[key(p)]?{createNew:true}:{specId:specs.value[key(p)]!,configurationConfirmed:configurationConfirmed.value[key(p)]})}))}:{}),name:name.value.trim(),introduction:introduction.value.trim(),refs:data.photos.filter(p=>photos.value.includes(p.id)).map(p=>({...p,type:'file'})),requestId:requestId.value});if(result.status==='not_connected'||result.integrationStatus==='not_connected')ElMessage.success('已保存待上架；CRM／商城尚未接通，可在上架产品目录的待上架中查看');else ElMessage.success('上架确认已保存，以实际渠道状态为准');emit('saved',result)}catch(e){error.value=partnerError(e)}finally{busy.value=false}}
</script>
<template><el-dialog :model-value="true" title="确认上架" width="min(880px,96vw)" top="20px" class="catalog-listing-dialog" append-to-body :close-on-click-modal="false" :before-close="close"><div class="listing-content" v-loading="loading"><p>{{options?.catalogStyleLabel||options?.catalogStyleCode||row.catalogStyleCode}} · {{row.name}}</p><el-alert v-if="error" :title="error" type="error" :closable="false"><el-button v-if="!options" link @click="load">重试读取</el-button></el-alert><template v-if="options"><h3>本次决定经营的规格</h3><el-checkbox-group v-model="selected" class="listing-pairs" :disabled="busy"><div v-for="pair in options.pairs" :key="key(pair)" class="listing-pair"><el-checkbox :value="key(pair)" :disabled="!pair.eligible||busy">{{pair.specName}}</el-checkbox><span v-if="!pair.eligible" class="ineligible">{{pair.reason||'尚缺适用质检／签字依据'}}</span></div></el-checkbox-group><p v-if="!options.pairs.length">暂无明确选择的型号／颜色，请先回选品目录补齐。</p><el-form label-position="top" :disabled="busy"><el-form-item label="商品名称 *"><el-input v-model="name"/></el-form-item><el-form-item label="简短介绍 *"><el-input v-model="introduction" type="textarea" autosize/></el-form-item><h3>商品图片 *</h3><el-checkbox-group v-model="photos" class="listing-photos"><div v-for="photo in options.photos" :key="photo.id" class="listing-photo"><PartnerPhoto :id="photo.id" :allow-retry="true"/><el-checkbox :value="photo.id">{{photo.name}}</el-checkbox></div></el-checkbox-group><p v-if="!options.photos.length">本款尚无可公开商品图片；请先补齐，不采用受限成本原件。</p><el-form-item label="合作产品档案"><el-radio-group v-model="mode"><el-radio value="create">本次创建需要的档案</el-radio><el-radio value="existing">明确关联已有档案</el-radio></el-radio-group></el-form-item><template v-if="mode==='existing'"><el-form-item label="已有合作产品 *"><el-select v-model="productId" clearable filterable remote :remote-method="searchProducts" placeholder="搜索已有产品名称／编号"><el-option v-for="product in products" :key="product.id" :value="product.id" :label="product.name+' · '+product.code"/></el-select></el-form-item><el-form-item v-for="pair in selectedPairs" :key="key(pair)" :label="pair.specName+' · 关联已有规格 *'"><el-checkbox v-model="newSpecs[key(pair)]" :disabled="!productId">在已有商品下新建本规格</el-checkbox><template v-if="!newSpecs[key(pair)]"><OperationSpecPicker v-model="specs[key(pair)]" :product-id="productId" :supplier-code="options.supplierCode" :disabled="!productId"/><el-checkbox v-model="configurationConfirmed[key(pair)]" :disabled="!specs[key(pair)]">已核对型号、颜色及配置一致</el-checkbox></template></el-form-item></template></el-form><p class="listing-note">只处理本次明确规格；不创建正式SKU。{{options.externalListingConnected?'以外部实际结果更新上架状态。':'CRM／商城未接通：本次仅保存待上架，不显示已上架。'}}</p></template></div><template #footer><el-button :disabled="busy" @click="close">返回</el-button><el-button type="primary" :loading="busy" :disabled="!valid||loading" @click="submit">确认上架</el-button></template></el-dialog></template>
<style scoped>
:global(.catalog-listing-dialog){display:flex;flex-direction:column;max-height:calc(100dvh - 40px);margin-bottom:20px}:global(.catalog-listing-dialog>.el-dialog__body){min-height:0;overflow-y:auto}:global(.catalog-listing-dialog>.el-dialog__footer){display:flex;gap:8px;justify-content:flex-end;flex-wrap:wrap}
.listing-content{min-width:0;font-size:13px;line-height:1.6}.listing-content h3{font-size:14px;margin:10px 0 6px}.listing-content p{overflow-wrap:anywhere}.listing-pairs{display:flex;flex-direction:column;gap:4px}.listing-pairs>.listing-pair{display:flex;gap:6px;flex-wrap:wrap;align-items:center}.listing-pairs :deep(.el-checkbox){height:auto;white-space:normal;margin:0}.listing-pairs :deep(.el-checkbox__label){white-space:normal;overflow-wrap:anywhere}.ineligible,.listing-note{font-size:12px;color:var(--el-text-color-secondary)}.listing-photos{display:flex;gap:8px;flex-wrap:wrap}.listing-photos>.listing-photo{display:flex;gap:7px;align-items:center;min-width:0;max-width:100%;border:1px solid var(--el-border-color-lighter);padding:6px;border-radius:5px}.listing-photos :deep(.el-checkbox__label){white-space:normal;overflow-wrap:anywhere}.listing-content :deep(.el-select){width:100%}
</style>
